local config = {
  str_homestory_N23paixi_90040101_1_dialog_content = "Vice, sobre lo que me dijiste ayer...",
  str_homestory_N23paixi_90040101_2_dialog_content = "¡Dormí en él y creo que es realmente factible!",
  str_homestory_N23paixi_90040101_3_dialog_content = "Jejeje, sabía que me atraparías, PlayerName!",
  str_homestory_N23paixi_90040101_4_dialog_content = "Sé que ya llevo un diario todos los días...",
  str_homestory_N23paixi_90040101_5_dialog_content = "pero sigo pensando que sería mejor documentar nuestras experiencias en video.",
  str_homestory_N23paixi_90040101_6_dialog_content = "Sí, hemos pasado por las cosas más interesantes juntos.",
  str_homestory_N23paixi_90040101_7_dialog_content = "¡Exactamente!",
  str_homestory_N23paixi_90040101_8_dialog_content = "Si pudiéramos filmarlos en una forma artística como un <color=#FFB400>película</color>, eso sería sorprendente.",
  str_homestory_N23paixi_90040101_9_dialog_content = "Mmm. ¡Así es!",
  str_homestory_N23paixi_90040101_10_dialog_content = "Hmm, en esa nota...",
  str_homestory_N23paixi_90040101_11_dialog_content = "Si queremos hacer una película, tenemos que hacer una <color=#FFB400>estudio de cine</color> ¿primera a la derecha?",
  str_homestory_N23paixi_90040101_12_dialog_content = "Supongo que sí.",
  str_homestory_N23paixi_90040101_13_dialog_content = "Creo que puedo dejarte los planos arquitectónicos y esas cosas, Vice.",
  str_homestory_N23paixi_90040101_14_dialog_content = "Sé que eres bueno en esas cosas.",
  str_homestory_N23paixi_90040101_15_dialog_content = "¿Eh? Bueno, sé cómo diseñar planos y esas cosas...",
  str_homestory_N23paixi_90040101_16_dialog_content = "Pero no sé nada sobre equipos de filmación.",
  str_homestory_N23paixi_90040101_17_dialog_content = "¡¿Q-Qué?!",
  str_homestory_N23paixi_90040101_18_dialog_content = "¿Hay planos que ni siquiera tú puedes diseñar?",
  str_homestory_N23paixi_90040101_19_dialog_content = "H-Oye! ¿Se supone que eso es un cumplido o un insulto?",
  str_homestory_N23paixi_90040101_20_dialog_content = "Estoy conmocionado.",
  str_homestory_N23paixi_90040101_21_dialog_content = "Hmm... Películas, un estudio de cine... equipo de filmación, un productor...",
  str_homestory_N23paixi_90040101_22_dialog_content = "¿Productor?",
  str_homestory_N23paixi_90040101_23_dialog_content = "¡Derecha! ¡Productor!",
  str_homestory_N23paixi_90040101_24_dialog_content = "PlayerName, por qué no preguntamos <color=#FFB400>Minos</color>?",
  str_homestory_N23paixi_90040101_25_dialog_content = "Quiero decir, tiene experiencia reciente. ¡Podemos pedirle ayuda!",
  str_homestory_N23paixi_90040101_26_dialog_content = "¡Estás en lo correcto!",
  str_homestory_N23paixi_90040101_27_dialog_content = "Vamos a preguntarle.",
  str_homestory_N23paixi_90040102_1_dialog_content = "¡Hola, Miños!",
  str_homestory_N23paixi_90040102_2_dialog_content = "Buenas tardes honorable PlayerName.",
  str_homestory_N23paixi_90040102_3_dialog_content = "Tengo una pregunta que hacerte, si no te importa, por supuesto.",
  str_homestory_N23paixi_90040102_4_dialog_content = "Por supuesto. Me alegra ser de cualquier ayuda que pueda ser.",
  str_homestory_N23paixi_90040102_5_dialog_content = "Cierto.",
  str_homestory_N23paixi_90040102_6_dialog_content = "Las preferencias dietéticas de Miss Nina han cambiado recientemente. ella está realmente interesada <color=#FFB400>pez</color> ahora.",
  str_homestory_N23paixi_90040102_7_dialog_content = "Ahora, normalmente debería ser yo quien prepare sus comidas, ya que soy su mayordomo.",
  str_homestory_N23paixi_90040102_8_dialog_content = "Pero, ahora mismo, estoy tratando de revisar y registrar mi experiencia como productor.",
  str_homestory_N23paixi_90040102_9_dialog_content = "En lugar de distraerme y pasar a otra cosa a la mitad, espero poder terminar mi revisión primero.",
  str_homestory_N23paixi_90040102_10_dialog_content = "Pero si hago eso, definitivamente habrá pasado la hora del almuerzo cuando regrese con un pescado para cocinar.",
  str_homestory_N23paixi_90040102_11_dialog_content = "Ya veo. Entonces quieres que lo haga <color=#FFB400>atrapar algunos peces</color> para ti, ¿verdad?",
  str_homestory_N23paixi_90040102_12_dialog_content = "Eso es correcto. Le agradecería que me dedicara algo de tiempo para hacer eso por mí en este momento. PlayerName.",
  str_homestory_N23paixi_90040102_13_dialog_content = "¡Por supuesto! ¡Usted puede contar conmigo!",
  str_homestory_N23paixi_90040102_X13_dialog_content = "Ah, casi me olvido de preguntar.",
  str_homestory_N23paixi_90040102_X14_dialog_content = "¿Qué tipo de pescado necesitas?",
  str_homestory_N23paixi_90040102_X15_dialog_content = "Disculpa, debería habértelo dicho.",
  str_homestory_N23paixi_90040102_X16_dialog_content = "Últimamente, Miss Nina ha estado disfrutando de Knifefish.",
  str_homestory_N23paixi_90040102_X17_dialog_content = "Muy bien, ¡lo tengo! Déjamelo a mí.",
  str_homestory_N23paixi_90040102_14_dialog_content = "Por cierto, ¿a qué te refieres con \"revisar\"?",
  str_homestory_N23paixi_90040102_15_dialog_content = "Quiero hacer un registro completo de mi experiencia reciente como productor.",
  str_homestory_N23paixi_90040102_16_dialog_content = "Por ejemplo, cómo se construye un escenario, qué se requiere del equipo para hacer una película y cómo operar el equipo necesario.",
  str_homestory_N23paixi_90040102_17_dialog_content = "Por supuesto, no es porque sea un fanático de las películas que estoy haciendo esto.",
  str_homestory_N23paixi_90040102_18_dialog_content = "Solo quiero estar preparado si la señorita Nina de repente se interesa algún día.<sprite=emo_mojing size=60 />",
  str_homestory_N23paixi_90040102_19_dialog_content = "Comprendo.",
  str_homestory_N23paixi_90040102_20_dialog_content = "En realidad, necesito esa \"revisión\" tuya. Es por eso que estoy aquí.",
  str_homestory_N23paixi_90040102_21_dialog_content = "Después de que regrese con tu pez, ¿puedes decirme qué implica hacer una película?",
  str_homestory_N23paixi_90040102_22_dialog_content = "Por supuesto. Estaré encantado de ayudar.",
  str_homestory_N23paixi_90040102_23_dialog_content = "Estaré esperando tu regreso, entonces.",
  str_homestory_N23paixi_90040103_1_dialog_content = "Eso fue mucho más rápido de lo que esperaba.",
  str_homestory_N23paixi_90040103_2_dialog_content = "¡Por supuesto! ({1}/{2})",
  str_homestory_N23paixi_90040103_5_dialog_content = "Gracias. Te pagaré con lo que necesites de mí.",
  str_homestory_N23paixi_90040103_6_dialog_content = "He completado mi revisión.",
  str_homestory_N23paixi_90040103_7_dialog_content = "Ahora, déjame confirmar lo que quieres de mí...",
  str_homestory_N23paixi_90040103_8_dialog_content = "Quieres hacer un estudio de cine en Cloud Gardens, ¿sí?",
  str_homestory_N23paixi_90040103_9_dialog_content = "Así es.",
  str_homestory_N23paixi_90040103_10_dialog_content = "Pero realmente no sé qué tipo de equipo necesitaremos...",
  str_homestory_N23paixi_90040103_11_dialog_content = "Comprendo.",
  str_homestory_N23paixi_90040103_12_dialog_content = "Anteriormente, logré compilar una lista de todas las cosas que necesitará para hacer un estudio de cine.",
  str_homestory_N23paixi_90040103_13_dialog_content = "Puedo proporcionarle la mayoría de los equipos y materiales de construcción directamente.",
  str_homestory_N23paixi_90040103_14_dialog_content = "Ejem, esto es, por supuesto, porque los Andersens te tienen en alta estima.",
  str_homestory_N23paixi_90040103_15_dialog_content = "Sin embargo, todavía necesito algunos materiales para hacer el <color=#FFB400>telones de fondo</color>.",
  str_homestory_N23paixi_90040103_16_dialog_content = "Los fondos también son necesarios para hacer películas, ¿verdad?",
  str_homestory_N23paixi_90040103_17_dialog_content = "Eso es correcto.",
  str_homestory_N23paixi_90040103_18_dialog_content = "Ah, ¡así que necesitas que reúna algunos materiales para ti!",
  str_homestory_N23paixi_90040103_19_dialog_content = "Sí. Necesitaré que te reúnas <color=#FFB400>10 madera</color> para mi.",
  str_homestory_N23paixi_90040103_20_dialog_content = "Una vez que tenga la madera, puedo empezar a hacer los fondos.",
  str_homestory_N23paixi_90040103_21_dialog_content = "También tendré otras cosas preparadas para ti.",
  str_homestory_N23paixi_90040103_22_dialog_content = "¡Eso es increíble! ¡Gracias Miños!",
  str_homestory_N23paixi_90040103_23_dialog_content = "¡Me pondré a ello, entonces!",
  str_homestory_N23paixi_90040103_24_dialog_content = "Muy apreciado, PlayerName.",
  str_homestory_N23paixi_90040103_3_dialog_content = "Todavía tengo un poco más para atrapar...",
  str_homestory_N23paixi_90040103_4_dialog_content = "Gracias por todo el trabajo duro, PlayerName.",
  str_homestory_N23paixi_90040104_1_dialog_content = "Eso fue mucho más rápido de lo que esperaba.",
  str_homestory_N23paixi_90040104_2_dialog_content = "¡Por supuesto! ({1}/{2})",
  str_homestory_N23paixi_90040104_5_dialog_content = "He preparado todo lo que necesitarás aquí mismo.",
  str_homestory_N23paixi_90040104_6_dialog_content = "Necesitaré algo de tiempo para pulir estos futuros fondos...",
  str_homestory_N23paixi_90040104_7_dialog_content = "Pronto podrás verlos, y todo lo demás que necesitarás para hacer películas.",
  str_homestory_N23paixi_90040104_8_dialog_content = "¡Estoy tan bendecido de tener un mayordomo como tú en Cloud Gardens, Minos!",
  str_homestory_N23paixi_90040104_9_dialog_content = "Me honra que pienses eso.",
  str_homestory_N23paixi_90040104_3_dialog_content = "Todavía necesito un poco más...",
  str_homestory_N23paixi_90040104_4_dialog_content = "Gracias por todo su arduo trabajo, PlayerName.",
  str_homestory_N23paixi_90040105_1_dialog_content = "¡Minos, eres realmente increíble! ¡Todo está hecho!",
  str_homestory_N23paixi_90040105_X1_dialog_content = "Me halagas.",
  str_homestory_N23paixi_90040105_2_dialog_content = "Ahora tengo que averiguar<sprite=emo_sikao size=60 /> donde deberíamos poner nuestro estudio de cine.",
  str_homestory_N23paixi_90040106_1_dialog_content = "¡Uf! Ahora que la ubicación está lista, mi estudio de cine realmente está tomando forma.",
  str_homestory_N23paixi_90040106_2_dialog_content = "Pero las cosas aquí parecen necesitar algo de limpieza y organización.",
  str_homestory_N23paixi_90040106_3_dialog_content = "El estudio de cine debería estar listo y funcionando una vez que todo esté limpio.",
  str_homestory_N23paixi_90040107_1_dialog_content = "Minos! Acabo de probar el equipo...",
  str_homestory_N23paixi_90040107_2_dialog_content = "¡Ellos son increíbles!",
  str_homestory_N23paixi_90040107_3_dialog_content = "Me alegra verte tan emocionado.",
  str_homestory_N23paixi_90040107_4_dialog_content = "De hecho, tengo una cosa más para ti, si estás dispuesto a aceptarla.",
  str_homestory_N23paixi_90040107_5_dialog_content = "Aquí hay un guión que recibí durante mi tiempo como productor.",
  str_homestory_N23paixi_90040107_6_dialog_content = "Ahora que tienes un estudio de cine aquí, creo que puede serte útil.",
  str_homestory_N23paixi_90040107_7_dialog_content = "Por supuesto, puedes rechazarme si ya tienes algo más en mente.",
  str_homestory_N23paixi_90040107_8_dialog_content = "De cualquier manera, creo que este script aún puede servir como una buena plantilla de referencia.",
  str_homestory_N23paixi_90040107_9_dialog_content = "¡Eso es realmente útil!",
  str_homestory_N23paixi_90040107_10_dialog_content = "¡Prometo hacer un buen uso de él, Minos!",
  str_homestory_N23paixi_90040107_11_dialog_content = "Yo... realmente no sé cómo agradecértelo.",
  str_homestory_N23paixi_90040107_12_dialog_content = "De nada, PlayerName.",
  str_homestory_N23paixi_90040107_13_dialog_content = "¿Vas a decirme que es solo otro de tus deberes esperados?",
  str_homestory_N23paixi_90040107_14_dialog_content = "Por una vez, acepta mi agradecimiento. ¿Por favor?",
  str_homestory_N23paixi_90040107_15_dialog_content = "Quiero decir, realmente me ayudaste.",
  str_homestory_N23paixi_90040107_16_dialog_content = "Ya veo. Bien entonces.",
  str_homestory_N23paixi_90040107_17_dialog_content = "Me tomaré muy en serio tu gratitud.",
  str_homestory_N23paixi_90040107_18_dialog_content = "¡De eso estoy hablando!",
  str_homestory_N23paixi_90040108_1_dialog_content = "¡Vice!",
  str_homestory_N23paixi_90040108_2_dialog_content = "¡Waaaah! ¡Estoy tan feliz! Yo lo veo, PlayerName!",
  str_homestory_N23paixi_90040108_3_dialog_content = "¡No puedo creer que ya hayas montado el estudio de cine!",
  str_homestory_N23paixi_90040108_4_dialog_content = "jajaja Aunque me alegro de que me felicites...",
  str_homestory_N23paixi_90040108_5_dialog_content = "Minos en realidad hizo la mayor parte del trabajo aquí.",
  str_homestory_N23paixi_90040108_6_dialog_content = "Todo lo que hice fue reunir materiales para él.",
  str_homestory_N23paixi_90040108_7_dialog_content = "Ah, claro...",
  str_homestory_N23paixi_90040108_8_dialog_content = "¿Crees que hay algo en el mundo que Minos no pueda hacer?",
  str_homestory_N23paixi_90040108_9_dialog_content = "En realidad, también tengo curiosidad por eso.",
  str_homestory_N23paixi_90040108_10_dialog_content = "De todos modos, se lo he agradecido mucho.",
  str_homestory_N23paixi_90040108_11_dialog_content = "Bien.",
  str_homestory_N23paixi_90040108_12_dialog_content = "Ahora que el estudio de cine está listo, ¡vamos a probarlo!",
  str_homestory_N23paixi_90040108_13_dialog_content = "¡Me lees la mente!",
  str_homestory_N23paixi_90040108_14_dialog_content = "Oh, y Minos me dio una <color=#FFB400>guion</color>.",
  str_homestory_N23paixi_90040108_15_dialog_content = "Ahora vamos a darle a esta cosa un buen estudio, ¿de acuerdo?",
  str_homestory_N23paixi_90040108_16_dialog_content = "Jejeje ¡La idea de estudiar nuevas máquinas me llena de emoción!",
  str_homestory_N23paixi_90040108_17_dialog_content = "No son solo máquinas, Vice... Esto es una forma de arte.",
  str_homestory_N23paixi_90040108_18_dialog_content = "¡Yo sé!",
  str_homestory_N23paixi_90040201_1_dialog_content = "Oye, PlayerName!",
  str_homestory_N23paixi_90040201_2_dialog_content = "¡Hola, Lilica!",
  str_homestory_N23paixi_90040201_3_dialog_content = "¡Guauuu! Realmente tengo que decir—",
  str_homestory_N23paixi_90040201_4_dialog_content = "¡Cloud Gardens es tan impresionante!",
  str_homestory_N23paixi_90040201_5_dialog_content = "¡Nunca hubiera pensado que habría un estudio de cine aquí!",
  str_homestory_N23paixi_90040201_6_dialog_content = "¡No solo eso, sino que todo el equipo se ve tan profesional también!",
  str_homestory_N23paixi_90040201_7_dialog_content = "¡Realmente eres súper considerado, como todos dicen!",
  str_homestory_N23paixi_90040201_8_dialog_content = "¡No sé cómo agradecerte por ocuparte de las necesidades de los entusiastas del cine como yo! ¡Eres increíble!",
  str_homestory_N23paixi_90040201_9_dialog_content = "E-Espera un minuto, Lilica.",
  str_homestory_N23paixi_90040201_10_dialog_content = "Minos en realidad proporcionó la mayoría de las cosas que ves en el estudio.",
  str_homestory_N23paixi_90040201_11_dialog_content = "¿Eh? ¿A él?",
  str_homestory_N23paixi_90040201_12_dialog_content = "Derecha. Eso explica mucho.",
  str_homestory_N23paixi_90040201_13_dialog_content = "Quiero decir, solo alguien con experiencia relevante podría hacer un estudio como este.",
  str_homestory_N23paixi_90040201_14_dialog_content = "Sí. Personalmente, no creo que hacer películas sea algo sencillo.",
  str_homestory_N23paixi_90040201_15_dialog_content = "Solo mira hacia allá...",
  str_homestory_N23paixi_90040201_16_dialog_content = "Los decorados y los fondos están listos.",
  str_homestory_N23paixi_90040201_17_dialog_content = "Pero todavía no sé exactamente cómo operar la cámara o encontrar a los actores adecuados para el trabajo.<sprite=emo_tanqi size=60 />",
  str_homestory_N23paixi_90040201_18_dialog_content = "Hmm, ¿es así?",
  str_homestory_N23paixi_90040201_19_dialog_content = "Bueno, no te preocupes, PlayerName. Puedo encargarme de encontrar los actores adecuados para ti.",
  str_homestory_N23paixi_90040201_20_dialog_content = "Sin embargo, sobre la cámara y esas cosas ... incluso si tengo algo de experiencia con ellos, todavía soy bastante novato.",
  str_homestory_N23paixi_90040201_21_dialog_content = "PlayerName, ¿por qué no le preguntas a esa chica linda que siempre tiene la nariz metida en un libro?",
  str_homestory_N23paixi_90040201_22_dialog_content = "No he estado aquí mucho tiempo, pero cada vez que la veo...",
  str_homestory_N23paixi_90040201_23_dialog_content = "Quiero decir CADA VEZ, ella siempre está leyendo.",
  str_homestory_N23paixi_90040201_24_dialog_content = "La chica de la que hablas... tiene el pelo castaño largo y rizado, ¿verdad?",
  str_homestory_N23paixi_90040201_25_dialog_content = "¡Sí!",
  str_homestory_N23paixi_90040201_26_dialog_content = "¡Se ve muy inteligente!",
  str_homestory_N23paixi_90040201_27_dialog_content = "Bueno, no podía ser nadie más.",
  str_homestory_N23paixi_90040201_28_dialog_content = "Supongo que iré y hablaré con <color=#FFB400>Hedy</color> ahora mismo, entonces.",
  str_homestory_N23paixi_90040201_29_dialog_content = "Entonces, ¿su nombre es Hedy?",
  str_homestory_N23paixi_90040201_30_dialog_content = "Lo sabía. Las chicas bonitas también tienen nombres bonitos.",
  str_homestory_N23paixi_90040201_31_dialog_content = "Esperaré tus buenas noticias, entonces, PlayerName!",
  str_homestory_N23paixi_90040202_1_dialog_content = "¿Mmm? Eres tu.",
  str_homestory_N23paixi_90040202_2_dialog_content = "Hola.",
  str_homestory_N23paixi_90040202_3_dialog_content = "¡Hola, Hedy!",
  str_homestory_N23paixi_90040202_4_dialog_content = "¿Qué estás haciendo?",
  str_homestory_N23paixi_90040202_5_dialog_content = "Lectura.",
  str_homestory_N23paixi_90040202_6_dialog_content = "Ah, sí, parece que lo haces mucho.",
  str_homestory_N23paixi_90040202_7_dialog_content = "Pero elegiste leer aquí hoy en lugar de leer en tu habitación.",
  str_homestory_N23paixi_90040202_8_dialog_content = "¿Estás tratando de preguntar por qué estoy leyendo aquí?",
  str_homestory_N23paixi_90040202_9_dialog_content = "Eres un agudo observador, te lo concedo.",
  str_homestory_N23paixi_90040202_10_dialog_content = "Para ser honesto, he estado leyendo libros sobre peces recientemente.",
  str_homestory_N23paixi_90040202_11_dialog_content = "Quería investigar un <color=#FFB400>Serpiente</color> en persona...",
  str_homestory_N23paixi_90040202_12_dialog_content = "Pero no sé dónde guardas tu equipo de pesca.",
  str_homestory_N23paixi_90040202_13_dialog_content = "Así que pensé en echar un vistazo alrededor...",
  str_homestory_N23paixi_90040202_14_dialog_content = "¿Equipo de pesca? Podrías haberme preguntado.",
  str_homestory_N23paixi_90040202_15_dialog_content = "¿Por qué le pediría a alguien que me ayude con algo tan insignificante?",
  str_homestory_N23paixi_90040202_16_dialog_content = "Uhm... está bien.",
  str_homestory_N23paixi_90040202_17_dialog_content = "En realidad, podemos saltarnos todo eso.",
  str_homestory_N23paixi_90040202_18_dialog_content = "¿Por qué no te consigo un Snakeel para que lo estudies? Quiero decir, si quieres que lo haga, eso es.",
  str_homestory_N23paixi_90040202_19_dialog_content = "No podría molestarte así...",
  str_homestory_N23paixi_90040202_20_dialog_content = "No te preocupes, porque también tengo algo que necesito preguntarte.",
  str_homestory_N23paixi_90040202_21_dialog_content = "¿Oh?",
  str_homestory_N23paixi_90040202_22_dialog_content = "...Ya veo.",
  str_homestory_N23paixi_90040202_23_dialog_content = "De hecho, tengo algunos libros sobre cine.",
  str_homestory_N23paixi_90040202_24_dialog_content = "Te los conseguiré en un rato si los necesitas.",
  str_homestory_N23paixi_90040202_25_dialog_content = "En realidad... Iré a mi habitación y te los traeré ahora mismo.",
  str_homestory_N23paixi_90040202_26_dialog_content = "¡Eso sería genial! ¡Gracias, Hedy!",
  str_homestory_N23paixi_90040202_27_dialog_content = "Mi placer.",
  str_homestory_N23paixi_90040202_28_dialog_content = "Nos reuniremos aquí y negociaremos, entonces.",
  str_homestory_N23paixi_90040202_29_dialog_content = "¡Lo tienes!",
  str_homestory_N23paixi_90040203_1_dialog_content = "¿Ya tienes tres Snakeels?",
  str_homestory_N23paixi_90040203_2_dialog_content = "¡Entiendo! ({1}/{2})",
  str_homestory_N23paixi_90040203_5_dialog_content = "Gracias.",
  str_homestory_N23paixi_90040203_3_dialog_content = "¡Todavía estoy trabajando en ello!",
  str_homestory_N23paixi_90040203_4_dialog_content = "Te deseo suerte.",
  str_homestory_N23paixi_90040204_1_dialog_content = "Aquí están los libros que querías.",
  str_homestory_N23paixi_90040204_2_dialog_content = "Los hojeé brevemente. El que mas recomiendo es <color=#FFB400>30 lecciones sobre cómo dirigir un estudio de cine</color>.",
  str_homestory_N23paixi_90040204_3_dialog_content = "No solo discute teorías, sino que también te enseña cómo aplicarlas usando ejemplos reales.",
  str_homestory_N23paixi_90040204_4_dialog_content = "El autor solía trabajar como miembro del equipo de filmación, por lo que también ofreció soluciones a muchos problemas comunes.",
  str_homestory_N23paixi_90040204_5_dialog_content = "En general, creo que este libro realmente te ayudará.",
  str_homestory_N23paixi_90040204_6_dialog_content = "¡Ya veo! Eres muy considerada, Hedy.",
  str_homestory_N23paixi_90040204_7_dialog_content = "¡Me aseguraré de estudiar cuidadosamente cada palabra de este libro!",
  str_homestory_N23paixi_90040204_8_dialog_content = "¡Ejem, cómo lees el libro no tiene nada que ver conmigo!<sprite=emo_baimao size=60 />",
  str_homestory_N23paixi_90040204_9_dialog_content = "¡De todas maneras, muchas gracias!",
  str_homestory_N23paixi_90040204_10_dialog_content = "Mi placer.",
  str_homestory_N23paixi_90040205_1_dialog_content = "¡Oh, vaya! ¿¡30 lecciones sobre cómo dirigir un estudio de cine!?",
  str_homestory_N23paixi_90040205_2_dialog_content = "¡Waaaah! ¡Tú y Hedy son maravillosos!",
  str_homestory_N23paixi_90040205_3_dialog_content = "¡Parece una gran lectura!",
  str_homestory_N23paixi_90040205_4_dialog_content = "¡Especialmente para mi!",
  str_homestory_N23paixi_90040205_5_dialog_content = "Ahora que tenemos este libro, si no logro convertirme en un verdadero actor en el futuro, ¡al menos puedo seguir trabajando entre el equipo!",
  str_homestory_N23paixi_90040205_6_dialog_content = "Wow Lilica, eso es muy... pragmático de tu parte!",
  str_homestory_N23paixi_90040205_7_dialog_content = "¡Por supuesto! Así llegué a donde estoy hoy.",
  str_homestory_N23paixi_90040205_8_dialog_content = "Bien. Ahora tenemos todo lo que necesitamos para hacer una película...",
  str_homestory_N23paixi_90040205_9_dialog_content = "y también nuestro primer guión, ¡además de un libro lleno de soluciones para situaciones de emergencia!",
  str_homestory_N23paixi_90040205_10_dialog_content = "Derecha. Así que podemos empezar a hacer películas, ¿verdad?",
  str_homestory_N23paixi_90040205_11_dialog_content = "¡Dame tiempo para leer este libro primero!",
  str_homestory_N23paixi_90040205_12_dialog_content = "¡Todavía tengo que aprender a operar el equipo!",
  str_homestory_N23paixi_90040205_13_dialog_content = "Derecha. Entonces lo leeré contigo.",
  str_homestory_N23paixi_90040301_1_dialog_content = "Jejeje, PlayerName! Tengo buenas noticias para ti.",
  str_homestory_N23paixi_90040301_2_dialog_content = "¡Nuestro estudio de cine está en pleno funcionamiento!",
  str_homestory_N23paixi_90040301_3_dialog_content = "¿Conoces todo el equipo que golpeamos tanto? ¡No están rotos en absoluto!",
  str_homestory_N23paixi_90040301_4_dialog_content = "No solo eso, ¡ya he hecho algunos cortos con ellos!",
  str_homestory_N23paixi_90040301_5_dialog_content = "Realmente el equipo es de buena calidad, jejeje.<sprite=emo_guilian size=60 />",
  str_homestory_N23paixi_90040301_6_dialog_content = "Ahahaha... Acerca de eso... Creo que a veces debemos ser más cuidadosos con el equipo.",
  str_homestory_N23paixi_90040301_7_dialog_content = "Si, tienes razón.",
  str_homestory_N23paixi_90040301_8_dialog_content = "Pero estoy aquí para hablar de negocios contigo.",
  str_homestory_N23paixi_90040301_9_dialog_content = "Muchos Aurorianos han visto el estudio.",
  str_homestory_N23paixi_90040301_10_dialog_content = "Me dijeron que también quieren hacer sus propias películas y tratar de hacer realidad sus propias ideas.",
  str_homestory_N23paixi_90040301_11_dialog_content = "Pero como no soy el jefe aquí, pensé que debería pedirte tu opinión.",
  str_homestory_N23paixi_90040301_12_dialog_content = "Por supuesto. No hay problema.",
  str_homestory_N23paixi_90040301_13_dialog_content = "¡Sí! ¡Sabía que dirías que está bien!",
  str_homestory_N23paixi_90040301_14_dialog_content = "Pero Lilica...",
  str_homestory_N23paixi_90040301_15_dialog_content = "Si esperamos hasta que todos tengan la oportunidad de familiarizarse con el equipo antes de empezar a hacer películas... ¿No sería una pérdida de tiempo?",
  str_homestory_N23paixi_90040301_16_dialog_content = "Jejeje, no te preocupes.",
  str_homestory_N23paixi_90040301_17_dialog_content = "¡El que blande la cámara no será otro que atentamente, Lilica, la prometedora directora!",
  str_homestory_N23paixi_90040301_18_dialog_content = "¡Al ayudar a todos a cumplir sus deseos de hacer sus propias películas, también podré obtener mucha experiencia práctica en filmación!",
  str_homestory_N23paixi_90040301_19_dialog_content = "Es una situación en la que todos ganan, se mire como se mire.",
  str_homestory_N23paixi_90040301_20_dialog_content = "¡Así que no te preocupes por los problemas técnicos!",
  str_homestory_N23paixi_90040301_21_dialog_content = "Bien entonces.",
  str_homestory_N23paixi_90040301_22_dialog_content = "Confío en tu profesionalidad, Lilica.",
  str_homestory_N23paixi_90040301_23_dialog_content = "Muy bueno!",
  str_homestory_N23paixi_90040301_24_dialog_content = "¡Ahora, debemos ponernos en marcha y comenzar a ayudar a nuestro primer cliente!",
  str_homestory_N23paixi_90040301_25_dialog_content = "¿Nuestro primer cliente?",
  str_homestory_N23paixi_90040301_26_dialog_content = "¡Es Correcto!",
  str_homestory_N23paixi_90040301_27_dialog_content = "Sadie te está esperando en <color=#FFB400>Plaza Jacinto</color>!",
  str_homestory_N23paixi_90040301_28_dialog_content = "¿Eh? ¿Por qué yo?",
  str_homestory_N23paixi_90040301_29_dialog_content = "¡Porque tengo que quedarme aquí y familiarizarme con el equipo!",
  str_homestory_N23paixi_90040301_30_dialog_content = "Y conoces a todos aquí más que yo, ¿no?",
  str_homestory_N23paixi_90040301_31_dialog_content = "Correcto... Está bien. Te veré luego, entonces.",
  str_homestory_N23paixi_90040301_32_dialog_content = "Estaré esperando aquí mismo.",
  str_homestory_N23paixi_90040302_1_dialog_content = "finalmente estás aquí, PlayerName. Te he estado anticipando.",
  str_homestory_N23paixi_90040302_2_dialog_content = "¡Hola, Sadie!",
  str_homestory_N23paixi_90040302_3_dialog_content = "Lilica me dijo que quieres hacer una película sobre espadachines, ¿verdad?",
  str_homestory_N23paixi_90040302_4_dialog_content = "¡Es Correcto!",
  str_homestory_N23paixi_90040302_5_dialog_content = "Tengo ideas, pero ningún plan concreto.",
  str_homestory_N23paixi_90040302_6_dialog_content = "Hay muchas chicas geniales aquí, pero yo no soy una de ellas.",
  str_homestory_N23paixi_90040302_7_dialog_content = "¡Pero esto no cambia el hecho de que quiero hacer una verdadera película de espadachines!",
  str_homestory_N23paixi_90040302_8_dialog_content = "Uhm... ¿Por qué no me cuentas tu idea primero?",
  str_homestory_N23paixi_90040302_9_dialog_content = "Luego veremos si podemos hacerlo realidad.",
  str_homestory_N23paixi_90040302_10_dialog_content = "Primero, quiero que tenga lugar de noche. Una noche muy oscura.",
  str_homestory_N23paixi_90040302_11_dialog_content = "Segundo, quiero que haya muchos enemigos en guardia.",
  str_homestory_N23paixi_90040302_12_dialog_content = "Tercero, quiero que les pidas algo a las chicas geniales por mí.",
  str_homestory_N23paixi_90040302_13_dialog_content = "Cada vez que trato de preguntarles yo mismo, entran en pánico y se esconden.",
  str_homestory_N23paixi_90040302_14_dialog_content = "Es como si estuvieran preocupados de que yo sea peligroso y que los secuestre o algo así.",
  str_homestory_N23paixi_90040302_15_dialog_content = "Uhm... Entonces, ¿a quién quieres que le pregunte?",
  str_homestory_N23paixi_90040302_16_dialog_content = "Allura! Allura!",
  str_homestory_N23paixi_90040302_17_dialog_content = "Está bien...",
  str_homestory_N23paixi_90040302_18_dialog_content = "Solo quieres que le pregunte cómo es un día en su vida como mercenario maduro y genial, ¿verdad?",
  str_homestory_N23paixi_90040302_19_dialog_content = "¡Si si si!",
  str_homestory_N23paixi_90040302_20_dialog_content = "Quédate aquí. Volveré enseguida.",
  str_homestory_N23paixi_90040302_21_dialog_content = "Tú Molas.<sprite=emo_dianzan size=60 />",
  str_homestory_N23paixi_90040303_1_dialog_content = "¿Necesitas algo?",
  str_homestory_N23paixi_90040303_2_dialog_content = "Ah, um... ¡Ejem!",
  str_homestory_N23paixi_90040303_3_dialog_content = "Solo quería saber cómo te estabas adaptando, Allura.",
  str_homestory_N23paixi_90040303_4_dialog_content = "Mientras pueda aceptar trabajos, el lugar donde vivo realmente no importa.",
  str_homestory_N23paixi_90040303_5_dialog_content = "¡Derecha! ¡Trabajos!",
  str_homestory_N23paixi_90040303_6_dialog_content = "¿Eh...?",
  str_homestory_N23paixi_90040303_7_dialog_content = "Derecha. Entonces, ¿cómo es tu día como un mercenario maduro y genial?",
  str_homestory_N23paixi_90040303_8_dialog_content = "¿Estás intentando que haga algo por ti gratis?",
  str_homestory_N23paixi_90040303_9_dialog_content = "¿Es por eso que estás tratando de halagarme?",
  str_homestory_N23paixi_90040303_10_dialog_content = "¡No! Tengo curiosidad. ¡Eso es todo! jajaja",
  str_homestory_N23paixi_90040303_11_dialog_content = "Depende del trabajo.",
  str_homestory_N23paixi_90040303_12_dialog_content = "Si es un trabajo de alto riesgo, entonces hago mi tarea y reúno toda la información que puedo antes de comenzar.",
  str_homestory_N23paixi_90040303_13_dialog_content = "En cuanto a los trabajos comunes y corrientes, trato de completarlos lo más rápido que puedo para poder pasar a otro.",
  str_homestory_N23paixi_90040303_14_dialog_content = "Puedo decir con certeza que la experiencia acumulada de todos esos pequeños trabajos diarios es crucial para el éxito de los trabajos de mayor riesgo.",
  str_homestory_N23paixi_90040303_15_dialog_content = "Te entrenan en puntería y combate físico, y también te preparan para mantener buenas relaciones con tus clientes.",
  str_homestory_N23paixi_90040303_16_dialog_content = "¡Correcto!",
  str_homestory_N23paixi_90040303_17_dialog_content = "Reunir... información... completar trabajos con prisa...",
  str_homestory_N23paixi_90040303_18_dialog_content = "Bueno. Lo tengo. ¡Gracias, Allura!",
  str_homestory_N23paixi_90040303_19_dialog_content = "¡Muchas gracias por compartir!",
  str_homestory_N23paixi_90040303_20_dialog_content = "Gracias por agradecerme.",
  str_homestory_N23paixi_90040303_21_dialog_content = "Ahora, paga.",
  str_homestory_N23paixi_90040303_22_dialog_content = "¡Lo sabía!",
  str_homestory_N23paixi_90040304_1_dialog_content = "¡Entrenamiento diario, sin demoras, recopilación de información y análisis de trabajo!",
  str_homestory_N23paixi_90040304_2_dialog_content = "¡Un asalto en toda regla en la oscuridad de la noche!",
  str_homestory_N23paixi_90040304_3_dialog_content = "Gracias, PlayerName!",
  str_homestory_N23paixi_90040304_4_dialog_content = "Ahora sé qué tipo de película quiero hacer.",
  str_homestory_N23paixi_90040304_5_dialog_content = "¡Solo necesito agregar algunas cosas más para que mi guión sea perfecto!",
  str_homestory_N23paixi_90040304_6_dialog_content = "¡Recibirás mi guión completo pronto!",
  str_homestory_N23paixi_90040304_7_dialog_content = "¡Muchas gracias! ¡Gracias, gracias, gracias, gracias!",
  str_homestory_N23paixi_90040304_8_dialog_content = "Bien bien. No tienes que decirlo tantas veces.",
  str_homestory_N23paixi_90040304_9_dialog_content = "Jeje.",
  str_homestory_N23paixi_90040304_10_dialog_content = "Tú Molas, PlayerName!<sprite=emo_dianzan size=60 />",
  str_homestory_N23paixi_90040305_1_dialog_content = "¿Entonces, cómo te fue? ¿Conseguiste una respuesta?",
  str_homestory_N23paixi_90040305_2_dialog_content = "Sí. Ahora sé cómo supuestamente pasa el día un mercenario genial.",
  str_homestory_N23paixi_90040305_3_dialog_content = "Jejeje, eso es genial.",
  str_homestory_N23paixi_90040305_4_dialog_content = "¡Ahora nuestro guión será aún mejor!",
  str_homestory_N23paixi_90040305_5_dialog_content = "¡No solo obtuvimos una excelente respuesta, sino que también podemos darle a la película un toque especial de Sadie!",
  str_homestory_N23paixi_90040305_6_dialog_content = "Supongo que podrías decirlo de esa manera, pero me pregunto cómo resultará la película basada en este guión...",
  str_homestory_N23paixi_90040305_7_dialog_content = "No puedo evitar sentirme preocupada.",
  str_homestory_N23paixi_90040305_8_dialog_content = "Bueno, así es como pienso en cosas como esta.",
  str_homestory_N23paixi_90040305_9_dialog_content = "Claro, todos somos novatos aquí, pero todos los \"profesionales\" también fueron novatos alguna vez. Han llegado a donde están ahora aprendiendo en el camino, ¿verdad?",
  str_homestory_N23paixi_90040305_10_dialog_content = "¿Y qué si esta película sale mal? ¡Aprenderemos de nuestros errores y seremos mejores la próxima vez!",
  str_homestory_N23paixi_90040305_11_dialog_content = "¡Tienes toda la razón, Lilica! ¡Ahora me siento emocionado!",
  str_homestory_N23paixi_90040305_12_dialog_content = "Entonces, ¡manos a la obra!",
  str_homestory_N23paixi_90040305_13_dialog_content = "¡Entendido!",
  str_homestory_N23paixi_90040401_1_dialog_content = "PlayerName...",
  str_homestory_N23paixi_90040401_2_dialog_content = "¿Qué pasa, Lilica?",
  str_homestory_N23paixi_90040401_3_dialog_content = "Pareces un poco molesto.",
  str_homestory_N23paixi_90040401_4_dialog_content = "Me preocupan los accesorios que necesitaremos para la película.",
  str_homestory_N23paixi_90040401_5_dialog_content = "¿Te refieres a la utilería de \"El espadachín\"?",
  str_homestory_N23paixi_90040401_6_dialog_content = "¡Exactamente!",
  str_homestory_N23paixi_90040401_7_dialog_content = "Sadie exigió que esta escena debe ser \"conmovedora\", ¡así que todo el presupuesto se destinará a ella!",
  str_homestory_N23paixi_90040401_8_dialog_content = "Pero a juzgar por la calidad de los accesorios que tenemos...",
  str_homestory_N23paixi_90040401_9_dialog_content = "No están a la altura de sus estándares, ¿verdad?",
  str_homestory_N23paixi_90040401_10_dialog_content = "No sólo sus estándares. Ni siquiera se encuentran con los míos.",
  str_homestory_N23paixi_90040401_11_dialog_content = "¿Debería... preguntarle sobre esto?",
  str_homestory_N23paixi_90040401_12_dialog_content = "Quiero decir, la mayoría de sus demandas tienden a ser abstractas y no concretas.<sprite=emo_baiyan size=60 />",
  str_homestory_N23paixi_90040401_13_dialog_content = "¡Eso seria genial!",
  str_homestory_N23paixi_90040401_14_dialog_content = "Gracias de antemano, PlayerName.",
  str_homestory_N23paixi_90040401_15_dialog_content = "Sin problema.",
  str_homestory_N23paixi_90040402_1_dialog_content = "¡Oh...!",
  str_homestory_N23paixi_90040402_2_dialog_content = "Entonces, ¿solo necesitas que te diga exactamente qué accesorios tengo en mente?",
  str_homestory_N23paixi_90040402_3_dialog_content = "Sí. Trate de ser detallado y específico.",
  str_homestory_N23paixi_90040402_4_dialog_content = "En esta escena, el espadachín mira a un <color=#FFB400>espejo</color> y expresa sus preocupaciones y su situación.",
  str_homestory_N23paixi_90040402_5_dialog_content = "Y luego llega el clímax de la película: ¡el espadachín se transforma!<sprite=emo_nuhuo size=60 />",
  str_homestory_N23paixi_90040402_6_dialog_content = "¡El espejo de repente emite una luz radiante de arco iris, y estrellas doradas brillantes y corazones rosas aparecen a su alrededor!",
  str_homestory_N23paixi_90040402_7_dialog_content = "¡Es mejor si podemos girar la cámara 360 grados alrededor del espadachín, con un primer plano del espadachín para mostrar que ha crecido!",
  str_homestory_N23paixi_90040402_8_dialog_content = "¡Sí, sí! ¡Y tan pronto como decide qué hacer, obtiene este misterioso poder mágico que la convierte en una mujer hermosa y fuerte!",
  str_homestory_N23paixi_90040402_9_dialog_content = "... ¿No es esto lo que llaman una transformación de chica mágica? ¿El tipo de cosas que solo suceden en los cómics de fantasía para niños?",
  str_homestory_N23paixi_90040402_10_dialog_content = "¿E-Eso no servirá?",
  str_homestory_N23paixi_90040402_11_dialog_content = "Yo... quiero decir, no se puede deshacer.",
  str_homestory_N23paixi_90040402_12_dialog_content = "De todos modos, todo lo que necesitas es ese espejo con los poderes mágicos, ¿verdad?",
  str_homestory_N23paixi_90040402_13_dialog_content = "Así es.",
  str_homestory_N23paixi_90040402_14_dialog_content = "Bueno, en ese caso... probablemente podamos hacer el marco del espejo de madera.",
  str_homestory_N23paixi_90040402_15_dialog_content = "¡Sí!",
  str_homestory_N23paixi_90040402_16_dialog_content = "Mmm, está bien.",
  str_homestory_N23paixi_90040402_17_dialog_content = "De todos modos, me iré <color=#FFB400>recoger un poco de madera</color> primero...",
  str_homestory_N23paixi_90040402_18_dialog_content = "Hacer el marco de un espejo parece bastante fácil.",
  str_homestory_N23paixi_90040402_19_dialog_content = "¡Sí!",
  str_homestory_N23paixi_90040402_20_dialog_content = "Oh, no debería haber dicho eso.",
  str_homestory_N23paixi_90040402_21_dialog_content = "Debería decir: gracias, PlayerName!",
  str_homestory_N23paixi_90040402_22_dialog_content = "Solo tráeme la madera. ¡Puedo hacer el marco yo mismo!",
  str_homestory_N23paixi_90040402_23_dialog_content = "Está bien...",
  str_homestory_N23paixi_90040403_1_dialog_content = "Eres tan rápido, PlayerName.",
  str_homestory_N23paixi_90040403_2_dialog_content = "Todo listo. ({1}/{2})",
  str_homestory_N23paixi_90040403_5_dialog_content = "¡Guau! Eres tan genial, PlayerName!",
  str_homestory_N23paixi_90040403_6_dialog_content = "¿De verdad puedes hacer el espejo de madera?",
  str_homestory_N23paixi_90040403_7_dialog_content = "¿Necesitas mi ayuda?",
  str_homestory_N23paixi_90040403_8_dialog_content = "Ten algo de fe en mí. Puedo hacerlo.",
  str_homestory_N23paixi_90040403_9_dialog_content = "Creo que vamos a necesitar algo de mineral.",
  str_homestory_N23paixi_90040403_10_dialog_content = "Correcto... Solo puedes hacer el marco básico de madera.",
  str_homestory_N23paixi_90040403_11_dialog_content = "necesitaremos <color=#FFB400>mineral</color> para hacer el espejo real.",
  str_homestory_N23paixi_90040403_12_dialog_content = "¡Bingo!",
  str_homestory_N23paixi_90040403_13_dialog_content = "Bien. Iré <color=#FFB400>recoger algo de mineral</color>, después.",
  str_homestory_N23paixi_90040403_14_dialog_content = "No es necesario que te esfuerces, ¿oíste? Podemos hacer el espejo juntos cuando regrese.",
  str_homestory_N23paixi_90040403_15_dialog_content = "¡Lo tengo!",
  str_homestory_N23paixi_90040403_3_dialog_content = "Sólo un poco más.",
  str_homestory_N23paixi_90040403_4_dialog_content = "¡Estaré esperando!",
  str_homestory_N23paixi_90040404_1_dialog_content = "Eres tan rápido, PlayerName.",
  str_homestory_N23paixi_90040404_2_dialog_content = "Todo listo. ({1}/{2})",
  str_homestory_N23paixi_90040404_5_dialog_content = "¡Guau! Eres muy guay, PlayerName!",
  str_homestory_N23paixi_90040404_6_dialog_content = "Ahora tenemos todo lo que necesitamos. Estoy feliz.",
  str_homestory_N23paixi_90040404_7_dialog_content = "Dame algo de tiempo, PlayerName. Me aseguraré de deslumbrarte con mi trabajo.",
  str_homestory_N23paixi_90040404_8_dialog_content = "¿De verdad no necesitas mi ayuda?",
  str_homestory_N23paixi_90040404_9_dialog_content = "Tú... ¿realmente sabes cómo hacer un espejo?",
  str_homestory_N23paixi_90040404_10_dialog_content = "He aceptado un trabajo como este antes. Tuve que sacar 31 espejos.<sprite=emo_mojing size=60 />",
  str_homestory_N23paixi_90040404_11_dialog_content = "¡Puedo hacer esto!",
  str_homestory_N23paixi_90040404_12_dialog_content = "Está bien... Si insistes.",
  str_homestory_N23paixi_90040404_13_dialog_content = "Vete, PlayerName! ¡Déjame con mi trabajo!",
  str_homestory_N23paixi_90040404_14_dialog_content = "Bien...",
  str_homestory_N23paixi_90040404_3_dialog_content = "Sólo un poco más.",
  str_homestory_N23paixi_90040404_4_dialog_content = "¡Estaré esperando!",
  str_homestory_N23paixi_90040405_1_dialog_content = "Jejeje PlayerName!",
  str_homestory_N23paixi_90040405_2_dialog_content = "¡Hola, Sadie!",
  str_homestory_N23paixi_90040405_3_dialog_content = "¿Cómo van las cosas?",
  str_homestory_N23paixi_90040405_4_dialog_content = "No te preocupes. Sólo quería ver si necesitabas una mano.",
  str_homestory_N23paixi_90040405_5_dialog_content = "¡Ya terminé de hacer el espejo mágico!",
  str_homestory_N23paixi_90040405_6_dialog_content = "Lo verás en un rato.",
  str_homestory_N23paixi_90040405_7_dialog_content = "¿En serio? ¿Entonces donde esta?",
  str_homestory_N23paixi_90040405_8_dialog_content = "Está en mi habitación. Primero tengo que pulirlo antes de mostrártelo.",
  str_homestory_N23paixi_90040405_9_dialog_content = "¡Todo lo que necesitas hacer es esperar!",
  str_homestory_N23paixi_90040405_10_dialog_content = "¿En serio? Eres más capaz de lo que imaginaba, Sadie.",
  str_homestory_N23paixi_90040405_11_dialog_content = "¡Oye!",
  str_homestory_N23paixi_90040405_12_dialog_content = "Ejem, quiero decir, ¡realmente eres capaz!",
  str_homestory_N23paixi_90040405_13_dialog_content = "Eso es mejor.",
  str_homestory_N23paixi_90040406_1_dialog_content = "holaaaa PlayerName!",
  str_homestory_N23paixi_90040406_2_dialog_content = "¿Conseguiste el accesorio? ¿Lo hiciste?",
  str_homestory_N23paixi_90040406_3_dialog_content = "Lo tengo lo tengo lo tengo.",
  str_homestory_N23paixi_90040406_4_dialog_content = "Entonces, ¿cuál era el accesorio que Sadie tenía en mente para la escena \"conmovedora\"?",
  str_homestory_N23paixi_90040406_5_dialog_content = "¡Soy muy curioso!",
  str_homestory_N23paixi_90040406_6_dialog_content = "Resulta que lo que ella seguía diciendo era un espejo.",
  str_homestory_N23paixi_90040406_7_dialog_content = "¿Un espejo?",
  str_homestory_N23paixi_90040406_8_dialog_content = "Sí. Francamente, no me puedo imaginar rodando la escena que tiene en mente, pero...",
  str_homestory_N23paixi_90040406_9_dialog_content = "Como dices, no estaría de más darle una oportunidad.",
  str_homestory_N23paixi_90040406_10_dialog_content = "¡Sí!",
  str_homestory_N23paixi_90040406_11_dialog_content = "¿Entonces estas lista?",
  str_homestory_N23paixi_90040406_12_dialog_content = "¡Podemos empezar a rodar la primera película de nuestro estudio!",
  str_homestory_N23paixi_90040406_13_dialog_content = "¡Sí, estoy listo!",
  str_homestory_N23paixi_90040406_14_dialog_content = "¡Bien! Después...",
  str_homestory_N23paixi_90040406_15_dialog_content = "Ahora que tenemos nuestro set, accesorios y equipo...",
  str_homestory_N23paixi_90040406_16_dialog_content = "¡Compensaremos todo lo demás que nos falta con nuestra pasión!",
  str_homestory_N23paixi_90040406_17_dialog_content = "¡Y ahora, pongamos a nuestra protagonista femenina en escena! ¡Sadie, la espadachín!",
  str_homestory_N23paixi_90040406_18_dialog_content = "¡Listo! ¿Todos en posición?",
  str_homestory_N23paixi_90040406_19_dialog_content = "Apoyar.",
  str_homestory_N23paixi_90040406_20_dialog_content = "¡Ahora, acción!<sprite=emo_laba size=60 />",
  str_homestory_N23paixi_90040406_21_dialog_content = "La historia...",
  str_homestory_N23paixi_90040406_22_dialog_content = "comienza en una noche escalofriante y negra como boca de lobo...",
  str_homestory_N23paixi_90040501_1_dialog_content = "PlayerName! ¡Buen tiempo! ¡Tengo algo que quería preguntarte!",
  str_homestory_N23paixi_90040501_2_dialog_content = "¿Qué tal?",
  str_homestory_N23paixi_90040501_3_dialog_content = "¿Sabes que acabamos de terminar de filmar The Swashbuckler?",
  str_homestory_N23paixi_90040501_4_dialog_content = "¿Paso algo? Aunque ya terminamos de filmar...",
  str_homestory_N23paixi_90040501_5_dialog_content = "¡Vaya! De nada. La película está lista. ¡No se trata de eso!",
  str_homestory_N23paixi_90040501_6_dialog_content = "Uf, eso es un alivio.",
  str_homestory_N23paixi_90040501_7_dialog_content = "Está esta chica mayor. Quiero decir, ella no es TAN vieja, pero al menos mayor que yo.",
  str_homestory_N23paixi_90040501_8_dialog_content = "Ha estado merodeando por el estudio últimamente.",
  str_homestory_N23paixi_90040501_9_dialog_content = "Pero cada vez que quiero acercarme a ella y preguntarle si quiere hacer una película,",
  str_homestory_N23paixi_90040501_10_dialog_content = "Siento que emite un aura escalofriante de ella y me asusta.",
  str_homestory_N23paixi_90040501_11_dialog_content = "¡Ver! ¡Ahí está ella!",
  str_homestory_N23paixi_90040501_12_dialog_content = "Oh eso es <color=#FFB400>paloma</color>.",
  str_homestory_N23paixi_90040501_13_dialog_content = "paloma De alguna manera, ese nombre suena familiar.<sprite=emo_yaosu size=60 />",
  str_homestory_N23paixi_90040501_14_dialog_content = "Bueno, ¿tal vez es porque ella también vivió en Umbraton por un tiempo?",
  str_homestory_N23paixi_90040501_15_dialog_content = "Pero mucha gente vive en Umbraton.",
  str_homestory_N23paixi_90040501_16_dialog_content = "Jaja, supongo que tienes razón.",
  str_homestory_N23paixi_90040501_17_dialog_content = "¡Hmph! Estás diciendo lo que sea, ¿no? PlayerName?",
  str_homestory_N23paixi_90040501_18_dialog_content = "¡Por qué no vas allí y le preguntas por qué ha estado dando vueltas por el estudio!",
  str_homestory_N23paixi_90040501_19_dialog_content = "Mi instinto me dice que quiere hacer una película pero no sabe cómo decírnoslo.",
  str_homestory_N23paixi_90040501_20_dialog_content = "Hmm, iré a averiguar.",
  str_homestory_N23paixi_90040502_1_dialog_content = "PlayerName.",
  str_homestory_N23paixi_90040502_2_dialog_content = "Hola, Paloma.",
  str_homestory_N23paixi_90040502_3_dialog_content = "Hola.<sprite=emo_baiyan size=60 />",
  str_homestory_N23paixi_90040502_4_dialog_content = "Uhm... ¡Ejem!",
  str_homestory_N23paixi_90040502_5_dialog_content = "¿Has... desarrollado un interés en el estudio de cine últimamente?",
  str_homestory_N23paixi_90040502_6_dialog_content = "Sí. Escuché que podías disparar lo que quisieras aquí.",
  str_homestory_N23paixi_90040502_7_dialog_content = "¡Es Correcto!",
  str_homestory_N23paixi_90040502_8_dialog_content = "Ya sea un documental de tus experiencias, o un sueño que quieras realizar, o la historia de otra persona...",
  str_homestory_N23paixi_90040502_9_dialog_content = "¡El equipo de nuestro estudio puede ayudarte a filmar cualquier cosa!",
  str_homestory_N23paixi_90040502_10_dialog_content = "¿Que necesito hacer?",
  str_homestory_N23paixi_90040502_11_dialog_content = "¿Ah?",
  str_homestory_N23paixi_90040502_12_dialog_content = "Digamos que quiero usar el equipo aquí para documentar cosas que suceden en la vida real y convertirlas en una película.",
  str_homestory_N23paixi_90040502_13_dialog_content = "De todos modos, en algo que sirva como documentación vívida.",
  str_homestory_N23paixi_90040502_14_dialog_content = "Si quiero hacer eso, ¿qué tengo que dar? ¿Qué quieres de mí?",
  str_homestory_N23paixi_90040502_15_dialog_content = "No puedo imaginar que estés dirigiendo una organización benéfica aquí, después de todo.",
  str_homestory_N23paixi_90040502_16_dialog_content = "Ejem. Bueno, si me preguntas cuánto cuesta... Es gratis.",
  str_homestory_N23paixi_90040502_17_dialog_content = "¡Por ahora al menos!",
  str_homestory_N23paixi_90040502_18_dialog_content = "En cuanto al futuro...",
  str_homestory_N23paixi_90040502_19_dialog_content = "Decidiremos si queremos cargar fuera de Cloud Gardens una vez que controlemos las operaciones...",
  str_homestory_N23paixi_90040502_20_dialog_content = "Mm... pensaremos en eso más tarde.",
  str_homestory_N23paixi_90040502_21_dialog_content = "Todo lo que tienes que saber es que, por ahora, ¡nuestro estudio es gratis!",
  str_homestory_N23paixi_90040502_22_dialog_content = "¿Oh?",
  str_homestory_N23paixi_90040502_23_dialog_content = "En pocas palabras, si hay una película que desea hacer, todo lo que tiene que hacer es enviarnos el guión y la utilería.",
  str_homestory_N23paixi_90040502_24_dialog_content = "Por supuesto, si no tienes los accesorios necesarios, puedo ayudarte a reunir materiales para hacerlos.",
  str_homestory_N23paixi_90040502_25_dialog_content = "O, si no sabes cómo escribir un guión... También puedo intentar...",
  str_homestory_N23paixi_90040502_26_dialog_content = "Ya sabes... ayudar a reunir algo de inspiración... o algo así.",
  str_homestory_N23paixi_90040502_27_dialog_content = "¿Quieres decir que no tengo que mover un dedo?",
  str_homestory_N23paixi_90040502_28_dialog_content = "¿Es eso lo que acabo de decir?",
  str_homestory_N23paixi_90040502_29_dialog_content = "¿No es eso básicamente lo que estás diciendo?",
  str_homestory_N23paixi_90040502_30_dialog_content = "Yo...",
  str_homestory_N23paixi_90040502_31_dialog_content = "Estoy bromeando.",
  str_homestory_N23paixi_90040502_32_dialog_content = "Yo... realmente no puedo decirlo por la seriedad en tu rostro.",
  str_homestory_N23paixi_90040502_33_dialog_content = "Tengo un guión listo.",
  str_homestory_N23paixi_90040502_34_dialog_content = "Lo que sí necesito es inspiración, preferiblemente cosas que sean reales y creíbles.",
  str_homestory_N23paixi_90040502_35_dialog_content = "En rigor, la película que quiero hacer... debería ser algo así como un documental.",
  str_homestory_N23paixi_90040502_36_dialog_content = "¿Un documental?",
  str_homestory_N23paixi_90040502_37_dialog_content = "Sí.",
  str_homestory_N23paixi_90040502_38_dialog_content = "Entiendo...",
  str_homestory_N23paixi_90040502_39_dialog_content = "Está bien, entendido.",
  str_homestory_N23paixi_90040502_40_dialog_content = "No te preocupes. ¡He hecho esto antes!",
  str_homestory_N23paixi_90040502_41_dialog_content = "Entonces, ¿de quién es la vida diaria que quieres que investigue como tu inspiración?",
  str_homestory_N23paixi_90040502_42_dialog_content = "<color=#FFB400>Sikare.</color>",
  str_homestory_N23paixi_90040502_43_dialog_content = "... ¿¡S-Sikare!?",
  str_homestory_N23paixi_90040502_44_dialog_content = "¿Hay algún problema? Las personas de diferentes profesiones seguramente llevan vidas diferentes.",
  str_homestory_N23paixi_90040502_45_dialog_content = "N-No hay problema...",
  str_homestory_N23paixi_90040502_46_dialog_content = "Y obviamente, estás más cerca de ella que yo.",
  str_homestory_N23paixi_90040502_47_dialog_content = "Por eso eres mejor para el trabajo.",
  str_homestory_N23paixi_90040502_48_dialog_content = "Está bien, entendido.",
  str_homestory_N23paixi_90040502_49_dialog_content = "Gracias.",
  str_homestory_N23paixi_90040502_50_dialog_content = "Estaré esperando aquí.",
  str_homestory_N23paixi_90040503_1_dialog_content = "¿Bola de nieve?",
  str_homestory_N23paixi_90040503_2_dialog_content = "Hola, Sikare.",
  str_homestory_N23paixi_90040503_3_dialog_content = "Mucho tiempo sin verlo.",
  str_homestory_N23paixi_90040503_4_dialog_content = "La vida idiota pero feliz de esos paramecios también te atrapó, ¿eh?",
  str_homestory_N23paixi_90040503_5_dialog_content = "Yo...",
  str_homestory_N23paixi_90040503_6_dialog_content = "No tengo idea de cómo responder a eso.",
  str_homestory_N23paixi_90040503_7_dialog_content = "Entiendo. Compartes \"lazos de amistad\" con ellos.",
  str_homestory_N23paixi_90040503_8_dialog_content = "¿Entonces por qué estás aquí?",
  str_homestory_N23paixi_90040503_9_dialog_content = "Bola de nieve, realmente eres especial, a diferencia de ese grupo.",
  str_homestory_N23paixi_90040503_10_dialog_content = "No tengo ningún deseo de hablar con ellos en absoluto. No soporto el olor a paramecio en ellos.",
  str_homestory_N23paixi_90040503_11_dialog_content = "Correcto... Déjame ser franco, Sikare.",
  str_homestory_N23paixi_90040503_12_dialog_content = "Paloma quiere que te pregunte cómo es tu día a día.",
  str_homestory_N23paixi_90040503_13_dialog_content = "¡Por favor, no lo malinterprete! Ella solo quiere hacer un documental sobre la vida cotidiana de todo tipo de personas.",
  str_homestory_N23paixi_90040503_14_dialog_content = "Entonces... ella me pidió que averiguara sobre el tuyo.",
  str_homestory_N23paixi_90040503_15_dialog_content = "Paloma... Yo sé quién es ella.",
  str_homestory_N23paixi_90040503_16_dialog_content = "Nos hemos encontrado. Aunque solo unas pocas veces.",
  str_homestory_N23paixi_90040503_17_dialog_content = "Parece que es un poco más inteligente que el resto de los paramecios.",
  str_homestory_N23paixi_90040503_18_dialog_content = "Por lo menos, fue lo suficientemente inteligente como para saber que obtendría sus respuestas si te enviaba.",
  str_homestory_N23paixi_90040503_19_dialog_content = "Pero ten esto en cuenta, Snowball.",
  str_homestory_N23paixi_90040503_20_dialog_content = "La única razón por la que estoy respondiendo a sus preguntas es porque eres tú quien me pregunta.",
  str_homestory_N23paixi_90040503_21_dialog_content = "Derecha. Gracias, Sikare.",
  str_homestory_N23paixi_90040503_22_dialog_content = "Comienzo mis días conversando con Faria.",
  str_homestory_N23paixi_90040503_23_dialog_content = "Si estoy de buen humor, no hago nada más que contemplar el cielo pacífico.<sprite=emo_pugongying size=60 />",
  str_homestory_N23paixi_90040503_24_dialog_content = "Si estoy de mal humor... entonces el cielo aquí no puede satisfacerme.",
  str_homestory_N23paixi_90040503_25_dialog_content = "Luego voy a donde pertenezco y le cuento a Faria las historias que he escuchado.",
  str_homestory_N23paixi_90040503_26_dialog_content = "Sobre el mundo exterior, sobre el cielo que cambia de color, los árboles que mudan sus hojas, y...",
  str_homestory_N23paixi_90040503_27_dialog_content = "Gente que camina por la tierra.",
  str_homestory_N23paixi_90040503_28_dialog_content = "Así son mis días.",
  str_homestory_N23paixi_90040503_29_dialog_content = "Me aseguraré de hacérselo saber a Paloma.",
  str_homestory_N23paixi_90040503_30_dialog_content = "Creo que estará satisfecha con esta respuesta.",
  str_homestory_N23paixi_90040503_31_dialog_content = "¿Ah?",
  str_homestory_N23paixi_90040503_32_dialog_content = "¿No me vas a dar la misma mirada lastimosa que todos los demás paramecios?",
  str_homestory_N23paixi_90040503_33_dialog_content = "Yo no te miraría así.",
  str_homestory_N23paixi_90040503_34_dialog_content = "Citando a Paloma...",
  str_homestory_N23paixi_90040503_35_dialog_content = "\"Las personas de diferentes profesiones seguramente llevan vidas diferentes\".",
  str_homestory_N23paixi_90040503_36_dialog_content = "Entonces, si así es tu día y no puedes cambiarlo, entonces deseo que seas feliz todos los días.",
  str_homestory_N23paixi_90040503_37_dialog_content = "...",
  str_homestory_N23paixi_90040503_38_dialog_content = "Ciertamente eres diferente a los demás, Snowball.",
  str_homestory_N23paixi_90040504_1_dialog_content = "PlayerName.",
  str_homestory_N23paixi_90040504_2_dialog_content = "Mmm...",
  str_homestory_N23paixi_90040504_3_dialog_content = "...",
  str_homestory_N23paixi_90040504_4_dialog_content = "... Entonces así son los días de Sikare.",
  str_homestory_N23paixi_90040504_5_dialog_content = "Comprendo.",
  str_homestory_N23paixi_90040504_6_dialog_content = "Gracias por ayudarme con la investigación.",
  str_homestory_N23paixi_90040504_7_dialog_content = "Me aseguraré de usarlo en mi guión.",
  str_homestory_N23paixi_90040504_8_dialog_content = "Lo tendrás muy pronto, junto con los accesorios que he preparado.",
  str_homestory_N23paixi_90040504_9_dialog_content = "Está bien...",
  str_homestory_N23paixi_90040504_10_dialog_content = "Y después de eso... dejaré mi documental en tus capaces manos.",
  str_homestory_N23paixi_90040504_11_dialog_content = "¡Derecha! ¡No hay problema!",
  str_homestory_N23paixi_90040504_12_dialog_content = "Gracias, PlayerName.",
  str_homestory_N23paixi_90040505_1_dialog_content = "Oye, PlayerName. ¿Como le fue?",
  str_homestory_N23paixi_90040505_2_dialog_content = "Bueno, tenías razón.",
  str_homestory_N23paixi_90040505_3_dialog_content = "Paloma sí quería hacer una película.",
  str_homestory_N23paixi_90040505_4_dialog_content = "Pero necesitaba material de inspiración especial, así que la ayudé.",
  str_homestory_N23paixi_90040505_5_dialog_content = "¡Wow!",
  str_homestory_N23paixi_90040505_6_dialog_content = "¡Pero todo eso ya está hecho!",
  str_homestory_N23paixi_90040505_7_dialog_content = "Su guión también está hecho.",
  str_homestory_N23paixi_90040505_8_dialog_content = "Incluso dijo que nos proporcionaría los accesorios.",
  str_homestory_N23paixi_90040505_9_dialog_content = "¡¡Guau!!",
  str_homestory_N23paixi_90040505_10_dialog_content = "¡Debe ser rica!<sprite=emo_baiyebi size=60 />",
  str_homestory_N23paixi_90040505_11_dialog_content = "Realmente no sé sobre eso.",
  str_homestory_N23paixi_90040505_12_dialog_content = "Pero ella no podría ser más pobre que nosotros dos.",
  str_homestory_N23paixi_90040505_13_dialog_content = "¡Estoy tan celoso!",
  str_homestory_N23paixi_90040505_14_dialog_content = "Bueno, de todos modos, ¡ahora estoy entusiasmado!",
  str_homestory_N23paixi_90040505_15_dialog_content = "¡Voy a adquirir todo tipo de habilidades y ganar mucho dinero con mis propias habilidades!",
  str_homestory_N23paixi_90040505_16_dialog_content = "PlayerName, hagamos rodar la cámara una vez que tengamos los accesorios.",
  str_homestory_N23paixi_90040505_17_dialog_content = "¡Entendido!",
  str_homestory_N23paixi_90040601_1_dialog_content = "¡Mi mas querido amigo!",
  str_homestory_N23paixi_90040601_2_dialog_content = "Caronte!",
  str_homestory_N23paixi_90040601_3_dialog_content = "¿También quieres hacer una película?",
  str_homestory_N23paixi_90040601_4_dialog_content = "¿Una película?",
  str_homestory_N23paixi_90040601_5_dialog_content = "No no no, PlayerName.",
  str_homestory_N23paixi_90040601_6_dialog_content = "Estaba admirando el tocadiscos aquí.<sprite=emo_yinfu size=60 />",
  str_homestory_N23paixi_90040601_7_dialog_content = "Derecha. Recuerdo que eras fan de eso.",
  str_homestory_N23paixi_90040601_8_dialog_content = "Una vez.",
  str_homestory_N23paixi_90040601_9_dialog_content = "¡Una vez consideré ese tocadiscos como mi cosa favorita en el mundo!",
  str_homestory_N23paixi_90040601_10_dialog_content = "¿Ah?",
  str_homestory_N23paixi_90040601_11_dialog_content = "Esperar. ¿Significa eso que te has enamorado de otro tocadiscos?",
  str_homestory_N23paixi_90040601_12_dialog_content = "De nada, mi querido amigo.",
  str_homestory_N23paixi_90040601_13_dialog_content = "Soy una persona muy leal.",
  str_homestory_N23paixi_90040601_14_dialog_content = "Dicho esto, creo que al tocadiscos le vendrían bien algunas mejoras.",
  str_homestory_N23paixi_90040601_15_dialog_content = "¿Qué quieres decir?",
  str_homestory_N23paixi_90040601_16_dialog_content = "Has construido un nuevo centro de artes aquí. Esa estructura encantadora difícilmente podría escapar de mi ojo.",
  str_homestory_N23paixi_90040601_17_dialog_content = "Pero me hizo pensar en la otra obra de arte en Cloud Gardens, el tocadiscos, eso es. Realmente podría usar una actualización.",
  str_homestory_N23paixi_90040601_18_dialog_content = "¡Vaya! ¡Música y cine!",
  str_homestory_N23paixi_90040601_19_dialog_content = "¡Solo cuando se combinan pueden adornar este lugar con la luz más glamorosa!",
  str_homestory_N23paixi_90040601_20_dialog_content = "Uhm... Está bien, puedo ver tu razonamiento detrás de eso.",
  str_homestory_N23paixi_90040601_21_dialog_content = "Pero en realidad no sé mucho de música. ¿Cómo crees que deberíamos mejorar el tocadiscos?",
  str_homestory_N23paixi_90040601_22_dialog_content = "Amigo mío, nada me complace más que responder a esta pregunta tuya.",
  str_homestory_N23paixi_90040601_23_dialog_content = "Se pueden hacer ajustes para que sus engranajes funcionen con mayor precisión, haciendo que la música suene aún mejor...",
  str_homestory_N23paixi_90040601_24_dialog_content = "¡Oh, el mero pensamiento de eso me emociona!<sprite=emo_aixin size=60 />",
  str_homestory_N23paixi_90040601_25_dialog_content = "¿Podría elaborar más sobre eso?",
  str_homestory_N23paixi_90040601_26_dialog_content = "¡Veo que estás tan emocionado como yo!",
  str_homestory_N23paixi_90040601_27_dialog_content = "¡Bueno! ¡Entonces no perdamos más tiempo!",
  str_homestory_N23paixi_90040601_28_dialog_content = "Por supuesto, puedes dejarme los ajustes a mí.",
  str_homestory_N23paixi_90040601_29_dialog_content = "Pero necesitaré que te ocupes de algo pequeño.",
  str_homestory_N23paixi_90040601_30_dialog_content = "Primero, necesitaré un poco de agua.",
  str_homestory_N23paixi_90040601_31_dialog_content = "Necesitamos que <color=#FFB400>ordenar los alrededores del tocadiscos</color>.",
  str_homestory_N23paixi_90040601_32_dialog_content = "De esa manera, puede volver a su antiguo yo radiante en el abrazo de un medio ambiente limpio.",
  str_homestory_N23paixi_90040601_33_dialog_content = "No hay problema.",
  str_homestory_N23paixi_90040601_34_dialog_content = "Entonces, me tomaré el tiempo de estudiar ese hermoso tocadiscos...",
  str_homestory_N23paixi_90040601_35_dialog_content = "y reflexionar sobre cómo hacerlo aún más radiante.",
  str_homestory_N23paixi_90040602_1_dialog_content = "Sé que nunca defraudarías a un artista.",
  str_homestory_N23paixi_90040602_2_dialog_content = "Así es. ({1}/{2})",
  str_homestory_N23paixi_90040602_5_dialog_content = "Excelente.",
  str_homestory_N23paixi_90040602_6_dialog_content = "Ahora que tenemos agua, podemos ordenar los alrededores del tocadiscos.",
  str_homestory_N23paixi_90040602_7_dialog_content = "¡Sí!",
  str_homestory_N23paixi_90040602_8_dialog_content = "Tomaré el área exterior. Te dejaré el área cerca del tocadiscos, ¿de acuerdo?",
  str_homestory_N23paixi_90040602_9_dialog_content = "En realidad, ¿por qué no me dejas toda la limpieza a mí, mi querida amiga?",
  str_homestory_N23paixi_90040602_10_dialog_content = "¿Eh? ¿Por qué?",
  str_homestory_N23paixi_90040602_11_dialog_content = "Creo que el tocadiscos necesita un poco de pulido para que exuda toda su belleza seductora y glamorosa.",
  str_homestory_N23paixi_90040602_12_dialog_content = "Creo que necesitaremos algunos <color=#FFB400>mineral</color>.",
  str_homestory_N23paixi_90040602_13_dialog_content = "¿Quieres pulir el tocadiscos con mineral?",
  str_homestory_N23paixi_90040602_14_dialog_content = "Así es, mi querido amigo.",
  str_homestory_N23paixi_90040602_15_dialog_content = "No tengo idea de lo que estás pensando, pero, de nuevo, tampoco puedo encontrarle ningún defecto.",
  str_homestory_N23paixi_90040602_16_dialog_content = "Oh, te lo prometo, lo entenderás una vez que veas los resultados.",
  str_homestory_N23paixi_90040602_17_dialog_content = "Está bien. Confío en ti.",
  str_homestory_N23paixi_90040602_18_dialog_content = "Se ha limpiado el entorno que rodea al tocadiscos... ¡pero no es suficiente!",
  str_homestory_N23paixi_90040602_19_dialog_content = "Todavía está a cierta distancia de lograr el brillante objetivo final.",
  str_homestory_N23paixi_90040602_20_dialog_content = "Sip.",
  str_homestory_N23paixi_90040602_3_dialog_content = "Sólo un momento...",
  str_homestory_N23paixi_90040602_4_dialog_content = "Derecha. Esperaré aquí con anticipación un poco más, entonces.",
  str_homestory_N23paixi_90040603_1_dialog_content = "Sé que no decepcionarás a un artista.",
  str_homestory_N23paixi_90040603_2_dialog_content = "Así es. ({1}/{2})",
  str_homestory_N23paixi_90040603_5_dialog_content = "Bien.",
  str_homestory_N23paixi_90040603_6_dialog_content = "¡Todos los materiales están listos!",
  str_homestory_N23paixi_90040603_7_dialog_content = "Querido amigo, debo agradecerte mucho por apoyar mi sueño.",
  str_homestory_N23paixi_90040603_8_dialog_content = "¿Es esto?",
  str_homestory_N23paixi_90040603_9_dialog_content = "En seguida.",
  str_homestory_N23paixi_90040603_10_dialog_content = "Mientras has estado ocupado ayudándome a lograr mi sueño, se me ocurrió cómo podemos actualizar ese hermoso tocadiscos.",
  str_homestory_N23paixi_90040603_11_dialog_content = "Todo lo que tienes que hacer ahora es esperar.",
  str_homestory_N23paixi_90040603_12_dialog_content = "Bien entonces.",
  str_homestory_N23paixi_90040603_13_dialog_content = "¡Gracias, Caronte!",
  str_homestory_N23paixi_90040603_14_dialog_content = "Soy yo quien debería estar agradeciéndote.",
  str_homestory_N23paixi_90040603_3_dialog_content = "Espera un segundo...",
  str_homestory_N23paixi_90040603_4_dialog_content = "Ah, esperaré aquí con anticipación un poco más, entonces.",
  str_homestory_N23paixi_90040604_1_dialog_content = "Vaya, PlayerName!",
  str_homestory_N23paixi_90040604_2_dialog_content = "¡Muchos Aurorianos han estado en nuestro estudio de cine!",
  str_homestory_N23paixi_90040604_3_dialog_content = "¡Sí! Vice, ¿has visto las películas que hicieron?",
  str_homestory_N23paixi_90040604_4_dialog_content = "Esperar. ¿Quieres decir que no solo estaban recorriendo el lugar, sino que en realidad hicieron películas?",
  str_homestory_N23paixi_90040604_5_dialog_content = "¡Es Correcto!",
  str_homestory_N23paixi_90040604_6_dialog_content = "Eso es increíble, PlayerName!",
  str_homestory_N23paixi_90040604_7_dialog_content = "Jajaja. Bueno, fue tu idea, así que no puedo llevarme todo el crédito.",
  str_homestory_N23paixi_90040604_8_dialog_content = "Es un poco egoísta felicitarse a uno mismo, pero aún tengo que decir: ¡Mira, te lo dije!",
  str_homestory_N23paixi_90040604_9_dialog_content = "¡Todos tienen experiencias que quieren documentar visualmente!",
  str_homestory_N23paixi_90040604_10_dialog_content = "Estás en lo correcto.",
  str_homestory_N23paixi_90040604_11_dialog_content = "Ah, pero en esa nota...",
  str_homestory_N23paixi_90040604_12_dialog_content = "Has estado trabajando duro, ¿no?",
  str_homestory_N23paixi_90040604_13_dialog_content = "Puedo arriesgarme a adivinar.",
  str_homestory_N23paixi_90040604_14_dialog_content = "Debe haber sido un trabajo duro poner en marcha el estudio de cine desde el estado en que estaba al principio.",
  str_homestory_N23paixi_90040604_15_dialog_content = "¡Decir ah! Bueno, todo lo que hice fue reunir materiales y hacer algunos recados.",
  str_homestory_N23paixi_90040604_16_dialog_content = "Minos, Lilica, Hedy, Sadie, Paloma y Charon se encargaron de la mayor parte del material técnico.",
  str_homestory_N23paixi_90040604_17_dialog_content = "¡Todos son increíbles!",
  str_homestory_N23paixi_90040604_18_dialog_content = "Asi que PlayerName, ¿has visto todas las películas que hicieron?",
  str_homestory_N23paixi_90040604_19_dialog_content = "No en su totalidad, no.",
  str_homestory_N23paixi_90040604_20_dialog_content = "Quiero decir, sé de qué tratan sus películas, pero...",
  str_homestory_N23paixi_90040604_21_dialog_content = "No he tenido la oportunidad de ver cómo resultaron.",
  str_homestory_N23paixi_90040604_22_dialog_content = "¡Bien! ¡Aquí está tu oportunidad!",
  str_homestory_N23paixi_90040604_23_dialog_content = "¿Qué tal si vamos a verlos juntos?",
  str_homestory_N23paixi_90040604_24_dialog_content = "¡Está bien!"
}
return config
